-- Re-pin the `reply-suggestion-v1` AI operation profile for databases migrated
-- before the 2026-08-19 reply-language contract change.
--
-- Bulgarian reached the reply-template catalogue without reaching
-- `CONCRETE_REPLY_LANGUAGE_PATTERN`, whose Cyrillic branch is now
-- `(?:uk|ru|bg)-Cyrl`. The pattern is derived into the JSON Schema sent to
-- OpenAI, so the model answered `languageCode: "bg-Cyrl"` correctly and the
-- gateway still rejected the response as `output_invalid` after a successful,
-- fully-billed provider call. Moving the pattern moves the reply output schema,
-- and with it the schema digest, the static token-bearing request bytes the
-- ceiling counts, and the operation profile digest.
--
-- Fresh databases get these values from the unshipped 0046 seed; this migration
-- is the forward fix for an already-migrated one and is a no-op there.
-- `ai_operation_profiles` is an immutable catalogue whose rows the runtime
-- byte-compares against the compiled contract at request time, so the seed must
-- move with the contract or every AI operation resolves `policy_unavailable`.
-- Same trigger-disable ceremony as 0050/0055/0057/0062.
ALTER TABLE "ai_operation_profiles" DISABLE TRIGGER "ai_operation_profiles_immutable";--> statement-breakpoint
UPDATE "ai_operation_profiles" AS target
   SET
       "command" = source."command",
       "capability" = source."capability",
       "purpose" = source."purpose",
       "source_route" = source."source_route",
       "gateway_path" = source."gateway_path",
       "caller_role" = source."caller_role",
       "capability_runtime_profile_version" = source."capability_runtime_profile_version",
       "provider_deployment_profile_version" = source."provider_deployment_profile_version",
       "output_schema_name" = source."output_schema_name",
       "output_schema_digest" = source."output_schema_digest",
       "prompt_digest" = source."prompt_digest",
       "artifact_attestations" = source."artifact_attestations",
       "artifact_attestations_digest" = source."artifact_attestations_digest",
       "sdk_request_shape_digest" = source."sdk_request_shape_digest",
       "static_token_bearing_bytes" = source."static_token_bearing_bytes",
       "static_token_bearing_digest" = source."static_token_bearing_digest",
       "source_byte_limit" = source."source_byte_limit",
       "provider_payload_byte_limit" = source."provider_payload_byte_limit",
       "prepared_request_byte_limit" = source."prepared_request_byte_limit",
       "response_byte_limit" = source."response_byte_limit",
       "max_output_tokens" = source."max_output_tokens",
       "provider_deadline_ms" = source."provider_deadline_ms",
       "request_deadline_ms" = source."request_deadline_ms",
       "execution_lease_ms" = source."execution_lease_ms",
       "profile_digest" = source."profile_digest"
  FROM (SELECT * FROM jsonb_populate_record(NULL::public.ai_operation_profiles, '{"profile_version":"reply-suggestion-v1","command":"reply","capability":"reply_drafting","purpose":"ai.generate_reply","source_route":"reply-suggestion","gateway_path":"/v1/reply-suggestion","caller_role":"web","capability_runtime_profile_version":"reply-drafting-runtime-v1","provider_deployment_profile_version":"private-beta-global-v1","output_schema_name":"reply_template_selection_v1","output_schema_digest":"d123646236e874e901bdd6706f98a3e607fe5f27d41318190efed543d27ba0cc","prompt_digest":"3d9ff8af03d9d9289db57ca29854a6daf0d337e1414c171d7e983648b0da75ca","artifact_attestations":{"source":{"sourcePolicyId":"google-business-profile-source-policy-v1","sourceCanonicalizerDigest":"df0c9ea9ea7efebe0fe270bb86f644a8dfffc411f58538bd6fc0634d295fcac5","redactionProfileVersion":"gbp-review-global-v1","redactionProfileDigest":"46f4024e09f1196f719f6120208b80ff13482bd3cbb57a5bf9ac9f0ed02eeab3","structuredMarkerDetectorVersion":"structured-marker-detectors-v1","structuredMarkerDetectorDigest":"fca2955d506787aa1aa4777cf55bb5020b571bc0e87c07c169c544f83a593e2a","languageCatalogueVersion":"ai-review-language-catalogue-v1","languageCatalogueDigest":"2229287cf869db0a5dbf64efc4f823e5a0f23f6da34a24b581585b06462bf1a5","replyLanguageVerifierVersion":"reply-language-verifier-v1","replyLanguageVerifierDigest":"3ed39117b80bfd90afa9b18a30f9c7406ce99bf709f32f5edb08829001c5a509","languageScriptConsistencyVersion":"language-script-consistency-v1","languageScriptConsistencyDigest":"16be4d6ec7e2bf13a4f059bc6249de7972fcb543e7989543b18903791fcb65fa","zhOrthographyVerifierVersion":"zh-orthography-verifier-v1","zhOrthographyVerifierDigest":"e9f945b7c0b8e6982de737a63819640263e14aad9c97e837056f5e1a952b729d","replyTemplateCatalogueVersion":"gbp-reply-template-catalogue-v1","replyTemplateCatalogueDigest":"ff5f572e9c8ce06fc384bdc4cdd911457510fdd0daed571a53d2348faa8bd89f","outputLeakageProfileVersion":"gbp-reply-output-leakage-v1","outputLeakageProfileDigest":"f25affbb40db8b68b4b5c4711f3eeddf41a2822c33c5c4f9b61faaec60533673"},"calendar":{"profileVersion":"property-calendar-v1","epochMillisFunction":"ai_epoch_millis_v1","localCalendarFunction":"resolve_ai_property_local_date_v1","localMidnightFunction":"ai_property_local_midnight_v1","databaseImageDigest":"33f923b05f64ca54ac4401c01126a6b92afe839a0aa0a52bc5aeb5cc958e5f20","testedPostgresMajorVersions":[16]},"sdk":{"requestShapeVersion":"openai-responses-request-shape-v1","requestShapeDigest":"6cb8b52a100a40f6564a7e48c97f0b7a145e630771bdaf1bc21024150b9f4850","providerTransportProfile":"openai-provider-transport-v1"},"gatewayBuild":{"version":"ai-egress-gateway-build-v1","digest":"9690cdf513d912f64b436c25270da811a45bc7f6f0f8652ca78178fd794b3fcd"}},"artifact_attestations_digest":"a2e0fff245e76e4c57cc495daccc6c3bc46c2ec98947e6f1efbae8773795f9d3","sdk_request_shape_digest":"6cb8b52a100a40f6564a7e48c97f0b7a145e630771bdaf1bc21024150b9f4850","static_token_bearing_bytes":906,"static_token_bearing_digest":"d31a938abc533fe9459a22d2c84d9f428a2497962106a97deeb4d6594e14c7f2","source_byte_limit":16384,"provider_payload_byte_limit":16384,"prepared_request_byte_limit":65536,"response_byte_limit":131072,"max_output_tokens":6144,"provider_deadline_ms":60000,"request_deadline_ms":70000,"execution_lease_ms":120000,"profile_digest":"c944fb02877ccd4fb5375610b826c37477bd19d93b176bfcef8fda1d37aa0681"}')) AS source
 WHERE target."profile_version" = 'reply-suggestion-v1';--> statement-breakpoint
ALTER TABLE "ai_operation_profiles" ENABLE TRIGGER "ai_operation_profiles_immutable";--> statement-breakpoint
DO $$
BEGIN
  IF (
    SELECT count(*) FROM public.ai_operation_profiles
     WHERE profile_version = 'reply-suggestion-v1'
       AND output_schema_digest = 'd123646236e874e901bdd6706f98a3e607fe5f27d41318190efed543d27ba0cc'
       AND static_token_bearing_bytes = 906
       AND static_token_bearing_digest = 'd31a938abc533fe9459a22d2c84d9f428a2497962106a97deeb4d6594e14c7f2'
       AND profile_digest = 'c944fb02877ccd4fb5375610b826c37477bd19d93b176bfcef8fda1d37aa0681'
  ) <> 1 THEN
    RAISE EXCEPTION 'reply-suggestion-v1 operation profile did not reach the bg-Cyrl output-schema re-pin';
  END IF;
END $$;--> statement-breakpoint
-- The readiness assertion byte-compares the exact catalogue projection, so
-- re-pinning the row above without re-pinning the assertion makes every caller
-- read "catalogue not ready" and the whole AI plane fails closed. Same body as
-- 0046/0062 with the reply-suggestion-v1 scalars moved.
